"use strict";(globalThis.webpackChunkdocs_site=globalThis.webpackChunkdocs_site||[]).push([[3568],{4857(e){e.exports=JSON.parse('{"version":{"pluginId":"default","version":"current","label":"Next","banner":null,"badge":false,"noIndex":false,"className":"docs-version-current","isLast":true,"docsSidebars":{"tutorialSidebar":[{"type":"link","href":"/GradCore-Tensor/docs/Intro","label":"Introduction","docId":"Intro","unlisted":false},{"type":"link","href":"/GradCore-Tensor/docs/Getting Started","label":"Getting Started","docId":"Getting Started","unlisted":false},{"type":"category","label":"Tutorials","collapsible":true,"collapsed":false,"items":[{"type":"link","href":"/GradCore-Tensor/docs/tutorials/tutorial-1-california-housing","label":"Tutorial 1: California Housing Regression","docId":"tutorials/tutorial-1-california-housing","unlisted":false},{"type":"link","href":"/GradCore-Tensor/docs/tutorials/tutorial-2-mnist","label":"Tutorial 2: MNIST Digit Classification","docId":"tutorials/tutorial-2-mnist","unlisted":false}],"href":"/GradCore-Tensor/docs/category/tutorials"},{"type":"category","label":"Tensor Module","collapsible":true,"collapsed":true,"items":[{"type":"link","href":"/GradCore-Tensor/docs/tensor_module/","label":"Tensor Module Overview","docId":"tensor_module/index","unlisted":false},{"type":"category","label":"Memory","collapsible":true,"collapsed":true,"items":[{"type":"link","href":"/GradCore-Tensor/docs/tensor_module/memory/arena","label":"Arena Allocator","docId":"tensor_module/memory/arena","unlisted":false},{"type":"link","href":"/GradCore-Tensor/docs/tensor_module/memory/platform","label":"Platform Layer","docId":"tensor_module/memory/platform","unlisted":false},{"type":"link","href":"/GradCore-Tensor/docs/tensor_module/memory/prng","label":"PRNG","docId":"tensor_module/memory/prng","unlisted":false}],"href":"/GradCore-Tensor/docs/category/memory"},{"type":"link","href":"/GradCore-Tensor/docs/tensor_module/tensor-basics","label":"Tensor Basics","docId":"tensor_module/tensor-basics","unlisted":false},{"type":"link","href":"/GradCore-Tensor/docs/tensor_module/tensor-views","label":"Tensor Views","docId":"tensor_module/tensor-views","unlisted":false},{"type":"category","label":"Arithmetic","collapsible":true,"collapsed":true,"items":[{"type":"link","href":"/GradCore-Tensor/docs/tensor_module/arithmetic/overview","label":"Arithmetic Operations","docId":"tensor_module/arithmetic/overview","unlisted":false}],"href":"/GradCore-Tensor/docs/category/arithmetic"},{"type":"category","label":"Activations","collapsible":true,"collapsed":true,"items":[{"type":"link","href":"/GradCore-Tensor/docs/tensor_module/activations/overview","label":"Activation Functions","docId":"tensor_module/activations/overview","unlisted":false}],"href":"/GradCore-Tensor/docs/category/activations"},{"type":"category","label":"Loss Functions","collapsible":true,"collapsed":true,"items":[{"type":"link","href":"/GradCore-Tensor/docs/tensor_module/loss_functions/overview","label":"Loss Functions","docId":"tensor_module/loss_functions/overview","unlisted":false},{"type":"link","href":"/GradCore-Tensor/docs/tensor_module/loss_functions/reduction-modes","label":"Reduction Modes","docId":"tensor_module/loss_functions/reduction-modes","unlisted":false}],"href":"/GradCore-Tensor/docs/category/loss-functions"},{"type":"link","href":"/GradCore-Tensor/docs/tensor_module/autograd-integration","label":"Tensors in the Autograd Engine","docId":"tensor_module/autograd-integration","unlisted":false}],"href":"/GradCore-Tensor/docs/category/tensor-module"}]},"docs":{"Getting Started":{"id":"Getting Started","title":"Getting Started","description":"Getting Started","sidebar":"tutorialSidebar"},"Intro":{"id":"Intro","title":"Introduction","description":"GradCore-Tensor is a compact, high-performance C++ library for building, training, and running neural networks with an API inspired by PyTorch. It provides a clear, object-oriented implementation of tensors, an autograd engine, neural network building blocks, optimizers, and a lightweight data pipeline \u2014 all implemented from first principles so you can read, understand, and extend every part of the stack.","sidebar":"tutorialSidebar"},"tensor_module/activations/overview":{"id":"tensor_module/activations/overview","title":"Activation Functions","description":"Activation functions introduce non-linearity into your network. Without them, a 47-layer neural network would have the expressive power of a single matrix multiply \u2014 and we\'d all be out of a hobby.","sidebar":"tutorialSidebar"},"tensor_module/arithmetic/overview":{"id":"tensor_module/arithmetic/overview","title":"Arithmetic Operations","description":"These are the low-level tensor math functions. Every layer in GradCore-Tensor ultimately calls one or more of these. They all follow the same conventions:","sidebar":"tutorialSidebar"},"tensor_module/autograd-integration":{"id":"tensor_module/autograd-integration","title":"Tensors in the Autograd Engine","description":"The tensor module provides the data. The autograd engine provides the memory of what you did with that data \u2014 so it can run the chain rule backwards. Here\'s how the two connect.","sidebar":"tutorialSidebar"},"tensor_module/index":{"id":"tensor_module/index","title":"Tensor Module Overview","description":"Welcome to the nerve centre of GradCore-Tensor. Everything \u2014 training, inference, backprop, your optimizer quietly panicking about learning rates \u2014 ultimately comes down to operations on Tensor objects. This section documents every corner of the tensor module so you know exactly what\'s happening under the hood.","sidebar":"tutorialSidebar"},"tensor_module/loss_functions/overview":{"id":"tensor_module/loss_functions/overview","title":"Loss Functions","description":"A loss function measures how wrong your model is. Training is the process of making it less wrong, one gradient at a time. Choosing the right loss function is not optional \u2014 using MSE for a classification problem is like using a ruler to measure temperature.","sidebar":"tutorialSidebar"},"tensor_module/loss_functions/reduction-modes":{"id":"tensor_module/loss_functions/reduction-modes","title":"Reduction Modes","description":"Reduction modes control whether a loss function returns a per-element tensor or collapses to a scalar. Every loss function in GradCore-Tensor accepts a Reduction argument.","sidebar":"tutorialSidebar"},"tensor_module/memory/arena":{"id":"tensor_module/memory/arena","title":"Arena Allocator","description":"The Arena is GradCore-Tensor\'s memory backbone. If you\'ve ever watched a neural network training session grind to a halt because malloc decided it was a great time to coalesce free blocks, you\'ll appreciate what an arena allocator does for you: it doesn\'t bother with any of that.","sidebar":"tutorialSidebar"},"tensor_module/memory/platform":{"id":"tensor_module/memory/platform","title":"Platform Layer","description":"platform.hpp is a thin wrapper around OS-level operations: virtual memory management and entropy generation. All the gritty mmap/munmap/mprotect calls live here so the rest of the codebase stays clean and portable (in theory \u2014 in practice it\'s Linux only, as the Introduction honestly admits).","sidebar":"tutorialSidebar"},"tensor_module/memory/prng":{"id":"tensor_module/memory/prng","title":"PRNG","description":"GradCore-Tensor uses a PCG (Permuted Congruential Generator) for all random number generation. PCG is fast, has excellent statistical properties, and produces 32 bits of randomness per step \u2014 which is exactly what you need for weight initialisation and data shuffling, and absolutely overkill for anything that doesn\'t need cryptographic security (which is everything in a neural network training loop).","sidebar":"tutorialSidebar"},"tensor_module/tensor-basics":{"id":"tensor_module/tensor-basics","title":"Tensor Basics","description":"The Tensor struct is the central data structure in GradCore-Tensor. It describes a multi-dimensional array of float values and knows how to index into them correctly, whether the data is contiguous in memory or is a strided view of something else.","sidebar":"tutorialSidebar"},"tensor_module/tensor-views":{"id":"tensor_module/tensor-views","title":"Tensor Views","description":"Views are tensors that share memory with another tensor. Changing the data through a view changes the original, and vice versa \u2014 because they\'re the same bytes, just described differently.","sidebar":"tutorialSidebar"},"tutorials/tutorial-1-california-housing":{"id":"tutorials/tutorial-1-california-housing","title":"Tutorial 1: California Housing Regression","description":"This tutorial walks through the California Housing dataset regression example end-to-end \u2014 from loading CSV data to running inference on unseen samples. By the end you will understand how CSVLoader, nn::Model, and the training loop fit together.","sidebar":"tutorialSidebar"},"tutorials/tutorial-2-mnist":{"id":"tutorials/tutorial-2-mnist","title":"Tutorial 2: MNIST Digit Classification","description":"This tutorial covers multi-class image classification using the MNIST handwritten digit dataset. You will learn how to set up batched loading with DataLoader, build a classifier, train with CrossEntropyLoss, evaluate test accuracy, and run per-sample inference with a visual terminal display.","sidebar":"tutorialSidebar"}}}}')}}]);